package app

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"

	"github.com/spf13/cobra"
)

const initTemplate = `# %[1]s — depengine project configuration
# Generated by 'depengine init'
# See: https://github.com/Khorea1/depengine
#
# Commit this file so everyone on the project gets the same declared tool set:
#   git add %[1]s depengine.lock && git commit
# Personal installation knowledge goes in ~/.config/depengine/manifest.toml.

schema_version = 1

[defaults]
manager = "native"

[tools]
# Tools whose package name is the same on every distro:
simple = [%s]

# Tools with custom package names or language ecosystem managers:
#   fd   = { apt = "fd-find" }
#   fzf  = { go  = "github.com/junegunn/fzf" }
#   ruff = { python = true }
#
# Full docs: https://github.com/Khorea1/depengine#readme
`

var toolNameRegex = regexp.MustCompile(`^[a-zA-Z0-9_][a-zA-Z0-9_.-]{0,128}$`)

// newInitCmd builds `depengine init`.
func newInitCmd() *cobra.Command {
	output := new(string)
	addTools := new(string)
	interactive := new(bool)
	fromState := new(string)
	fromManifest := new(string)
	dryRun := new(bool)

	cmd := &cobra.Command{
		Use:   "init",
		Short: ifPT("Inicializar schema.toml para um projeto", "Initialize a schema.toml for a new project"),
		Example: `  depengine init                          # scaffold with placeholder tools
  depengine init --add "zsh,bat,nvim"     # non-interactive tool list
  depengine init --add nvim --dry-run     # preview without creating files
  depengine init --from-state             # adopt installed tools from tracked state
  depengine init --from-manifest --dry-run  # adopt personal manifest entries without writing
  depengine init --schema path/to/schema.toml`,
		GroupID: groupManage,
		Args:    cobra.NoArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			if *fromState != "" && *fromManifest != "" {
				_, _ = fmt.Fprintln(os.Stderr, "error: --from-state and --from-manifest are mutually exclusive")
				return exitWithCode(2)
			}
			if (*fromState != "" || *fromManifest != "") && (*interactive || *addTools != "") {
				_, _ = fmt.Fprintln(os.Stderr, "error: --from-state/--from-manifest cannot be combined with --interactive or --add")
				return exitWithCode(2)
			}
			if *fromState != "" || *fromManifest != "" {
				return runInitAdopt(initAdoptOptions{
					Output:       *output,
					FromState:    *fromState,
					FromManifest: *fromManifest,
					DryRun:       *dryRun,
				})
			}
			if *interactive && *addTools != "" {
				_, _ = fmt.Fprintln(cmd.ErrOrStderr(), "error: --interactive and --add cannot be combined; use --add for non-interactive input")
				return exitWithCode(2)
			}
			return runInit(cmd, *output, *addTools, *interactive, *dryRun)
		},
	}
	f := cmd.Flags()
	f.StringVar(output, "schema", "", "path to write (default: schema.toml)")
	f.StringVar(addTools, "add", "", "comma-separated tool names to pre-populate (e.g. 'zsh,bat,nvim')")
	f.BoolVar(interactive, "interactive", false, "interactive mode: walk through adding tools")
	f.StringVar(fromState, "from-state", "", "adopt tools from tracked state (optional state file path)")
	f.Lookup("from-state").NoOptDefVal = "auto"
	f.StringVar(fromManifest, "from-manifest", "", "adopt tools from the personal manifest (optional manifest path)")
	f.Lookup("from-manifest").NoOptDefVal = "auto"
	f.BoolVar(dryRun, "dry-run", false, "print the resulting schema without writing it")
	return cmd
}

func runInit(cmd *cobra.Command, output, addTools string, interactive, dryRun bool) error {
	path := output
	if path == "" {
		path = "schema.toml"
	}
	stdout, stderr := cmd.OutOrStdout(), cmd.ErrOrStderr()

	if !dryRun {
		if _, err := os.Lstat(path); err == nil {
			_, _ = fmt.Fprintf(stderr, "error: %s already exists\n", path)
			return exitWithCode(1)
		} else if !os.IsNotExist(err) {
			_, _ = fmt.Fprintf(stderr, "error: cannot inspect %s: %v\n", path, err)
			return exitWithCode(1)
		}
	}

	if interactive {
		return runInteractiveInit(path, cmd.InOrStdin(), stdout, stderr, dryRun)
	}

	simpleList := `"tool1", "tool2"`
	if addTools != "" {
		names := strings.Split(addTools, ",")
		var quoted []string
		for _, n := range names {
			n = strings.TrimSpace(n)
			if n == "" {
				_, _ = fmt.Fprintln(stderr, "error: empty tool name (check for doubled commas or trailing comma)")
				return exitWithCode(1)
			}
			if !toolNameRegex.MatchString(n) {
				_, _ = fmt.Fprintf(stderr, "error: invalid tool name %q: use only letters, digits, underscores, hyphens, and dots\n", n)
				return exitWithCode(1)
			}
			quoted = append(quoted, fmt.Sprintf("%q", n))
		}
		simpleList = strings.Join(quoted, ", ")
	}

	template := fmt.Sprintf(initTemplate, filepath.Base(path), simpleList)
	if dryRun {
		_, _ = fmt.Fprintf(stderr, "Preview: %s (not written)\n", path)
		_, _ = io.WriteString(stdout, template)
		return nil
	}

	dir := filepath.Dir(path)
	if dir != "." {
		if err := os.MkdirAll(dir, 0o755); err != nil { // #nosec G301 -- Project schema parent directories are intentionally traversable by collaborators.
			_, _ = fmt.Fprintf(stderr, "error: cannot create directory %s: %v\n", dir, err)
			return exitWithCode(1)
		}
	}
	if err := os.WriteFile(path, []byte(template), 0o644); err != nil { // #nosec G306 -- schema.toml is a project file intended to be shared and committed.
		_, _ = fmt.Fprintf(stderr, "error: cannot write %s: %v\n", path, err)
		return exitWithCode(1)
	}

	// The ✓ goes to stdout (the created path is the consumable result,
	// pipeable), the hints go to stderr (guidance, not data).
	color := false
	if file, ok := stdout.(*os.File); ok {
		color = cliColor(file)
	}
	msg := fmt.Sprintf("✓ %s created", path)
	if addTools != "" {
		msg += fmt.Sprintf(" with %d tools", len(strings.Split(addTools, ",")))
	}
	_, _ = fmt.Fprintln(stdout, styled(color, ansiGreen, msg))
	_, _ = fmt.Fprintln(stderr, "Next: run 'depengine validate' to verify, or 'depengine install' to install.")
	_, _ = fmt.Fprintln(stderr, "Share this file with your team: git add schema.toml && git commit")
	return nil
}

func runInteractiveInit(path string, input io.Reader, stdout, stderr io.Writer, dryRun bool) error {
	r := bufio.NewReader(input)
	basename := filepath.Base(path)

	_, _ = fmt.Fprintln(stderr, "depengine init — interactive mode")
	_, _ = fmt.Fprintln(stderr, "Add tools one by one. Leave name empty to finish.")

	var simpleTools []string
	var customLines []string
	seen := make(map[string]bool)

	for {
		name, err := prompt(r, stderr, "Tool name (or empty to finish)")
		if err != nil {
			return initInputError(stderr, path, err)
		}
		if name == "" {
			break
		}
		if !toolNameRegex.MatchString(name) {
			_, _ = fmt.Fprintf(stderr, "Invalid tool name %q: use only letters, digits, underscores, hyphens, and dots.\n", name)
			continue
		}

		if seen[name] {
			_, _ = fmt.Fprintf(stderr, "⚠ %q already added. Enter another name.\n", name)
			continue
		}
		seen[name] = true

		_, _ = fmt.Fprintf(stderr, "\nHow does %s install?\n", name)
		choice, err := promptSelect(r, stderr, "Choose method", []string{
			"1) Native — same package name on every distro",
			"2) Native — different name on some distros",
			"3) Cargo (crates.io)",
			"4) Go (pkg.go.dev)",
			"5) Python (pip / pipx / uv)",
			"6) Node (npm / pnpm / bun)",
			"7) Git (clone + build)",
			"8) HTTP (download artifact)",
			"9) Other — skip, I'll edit manually",
		})
		if err != nil {
			return initInputError(stderr, path, err)
		}

		switch choice {
		case 0:
			simpleTools = append(simpleTools, name)
		case 1:
			overrides, err := promptMultiMap(r, stderr, "Native package overrides (enter names, empty = use tool name)", []string{"pacman", "apt", "brew", "dnf"})
			if err != nil {
				return initInputError(stderr, path, err)
			}
			var parts []string
			for _, mgr := range []string{"pacman", "apt", "brew", "dnf"} {
				if v, ok := overrides[mgr]; ok && v != "" {
					parts = append(parts, fmt.Sprintf("%s = %q", mgr, v))
				}
			}
			if len(parts) > 0 {
				customLines = append(customLines, fmt.Sprintf("%s = { %s }", name, strings.Join(parts, ", ")))
			} else {
				simpleTools = append(simpleTools, name)
			}
		case 2:
			// Cargo — ask for crate name if it differs from tool name
			pkg, err := prompt(r, stderr, "Crate name (empty if same as tool name)")
			if err != nil {
				return initInputError(stderr, path, err)
			}
			if pkg != "" {
				customLines = append(customLines, fmt.Sprintf("%s = { cargo = %q }", name, pkg))
			} else {
				customLines = append(customLines, fmt.Sprintf("%s = { cargo = true }", name))
			}
		case 3:
			// Go
			pkg, err := prompt(r, stderr, "Go module path (empty if same as tool name)")
			if err != nil {
				return initInputError(stderr, path, err)
			}
			if pkg != "" {
				customLines = append(customLines, fmt.Sprintf("%s = { go = %q }", name, pkg))
			} else {
				customLines = append(customLines, fmt.Sprintf("%s = { go = true }", name))
			}
		case 4:
			customLines = append(customLines, fmt.Sprintf("%s = { python = true }", name))
		case 5:
			customLines = append(customLines, fmt.Sprintf("%s = { node = true }", name))
		case 6:
			url, err := prompt(r, stderr, "Git repository URL")
			if err != nil {
				return initInputError(stderr, path, err)
			}
			if url == "" {
				url = "true"
			}
			customLines = append(customLines, fmt.Sprintf("%s = { git = %q }", name, url))
		case 7:
			url, err := prompt(r, stderr, "Download URL")
			if err != nil {
				return initInputError(stderr, path, err)
			}
			if url == "" {
				url = "true"
			}
			customLines = append(customLines, fmt.Sprintf("%s = { http = %q }", name, url))
		case 8:
			customLines = append(customLines, fmt.Sprintf("# %s = {  }  # TODO: configure manually", name))
		}

		_, _ = fmt.Fprintln(stderr)
	}

	var b strings.Builder
	fmt.Fprintf(&b, `# %s — depengine project configuration
# Generated by 'depengine init --interactive'
# See: https://github.com/Khorea1/depengine
#
# Commit this file so everyone on the project gets the same declared tool set:
#   git add %s depengine.lock && git commit
# Personal installation knowledge goes in ~/.config/depengine/manifest.toml.

schema_version = 1

[defaults]
manager = "native"

[tools]
`, basename, basename)

	if len(simpleTools) > 0 {
		quoted := make([]string, len(simpleTools))
		for i, n := range simpleTools {
			quoted[i] = fmt.Sprintf("%q", n)
		}
		fmt.Fprintf(&b, "simple = [%s]\n", strings.Join(quoted, ", "))
		if len(customLines) > 0 {
			b.WriteString("\n")
		}
	}

	for _, line := range customLines {
		b.WriteString(line + "\n")
	}

	if dryRun {
		_, _ = fmt.Fprintf(stderr, "Preview: %s (not written)\n", path)
		_, _ = io.WriteString(stdout, b.String())
		return nil
	}
	dir := filepath.Dir(path)
	if dir != "." {
		if err := os.MkdirAll(dir, 0o755); err != nil { // #nosec G301 -- Project schema parent directories are intentionally traversable by collaborators.
			_, _ = fmt.Fprintf(stderr, "error: cannot create directory %s: %v\n", dir, err)
			return exitWithCode(1)
		}
	}
	if err := os.WriteFile(path, []byte(b.String()), 0o644); err != nil { // #nosec G306 -- schema.toml is a project file intended to be shared and committed.
		_, _ = fmt.Fprintf(stderr, "error: cannot write %s: %v\n", path, err)
		return exitWithCode(1)
	}

	toolCount := len(simpleTools) + len(customLines)
	if toolCount == 0 {
		_, _ = fmt.Fprintf(stderr, "⚠ %s created — no tools added yet. Edit the file or re-run with --interactive.\n", path)
	} else {
		_, _ = fmt.Fprintf(stdout, "✓ %s created with %d tool(s)\n", path, toolCount)
	}
	_, _ = fmt.Fprintln(stderr)
	_, _ = fmt.Fprintln(stderr, "Next: run 'depengine validate' to verify, or 'depengine install' to install.")
	_, _ = fmt.Fprintln(stderr, "Share this file with your team: git add schema.toml && git commit")
	return nil
}

func initInputError(stderr io.Writer, path string, err error) error {
	_, _ = fmt.Fprintf(stderr, "error: interactive input ended (%v); %s was not written. Next: depengine init --add nvim\n", err, path)
	return exitWithCode(2)
}

// prompt reads a line from stdin, trimming whitespace. Returns io.EOF on Ctrl+D.
func prompt(r *bufio.Reader, stderr io.Writer, msg string) (string, error) {
	_, _ = fmt.Fprintf(stderr, "%s: ", msg)
	line, err := r.ReadString('\n')
	if err != nil {
		return "", err
	}
	return strings.TrimSpace(line), nil
}

// promptSelect shows a numbered menu and returns the 0-based choice.
func promptSelect(r *bufio.Reader, stderr io.Writer, msg string, options []string) (int, error) {
	for _, opt := range options {
		_, _ = fmt.Fprintln(stderr, "  "+opt)
	}
	for {
		input, err := prompt(r, stderr, msg)
		if err != nil {
			return 0, err
		}
		n, err := strconv.Atoi(input)
		if err != nil || n < 1 || n > len(options) {
			_, _ = fmt.Fprintf(stderr, "Enter a number between 1 and %d.\n", len(options))
			continue
		}
		return n - 1, nil
	}
}

// promptMultiMap reads values for each key and returns a map of key → value.
// Empty values are omitted from the result.
func promptMultiMap(r *bufio.Reader, stderr io.Writer, msg string, keys []string) (map[string]string, error) {
	_, _ = fmt.Fprintln(stderr, msg)
	result := make(map[string]string)
	for _, k := range keys {
		v, err := prompt(r, stderr, "  "+k)
		if err != nil {
			return nil, err
		}
		if v != "" {
			result[k] = v
		}
	}
	return result, nil
}
